#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Cell {
    int r, c;
    long long p;
    int id;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    int total_cells = n * m;
    vector<long long> P(total_cells);
    vector<Cell> cells(total_cells);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int id = i * m + j;
            cin >> P[id];
            cells[id] = {i, j, P[id], id};
        }
    }

    sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        return a.p < b.p;
    });

    vector<int> dsu_parent(total_cells);
    for (int i = 0; i < total_cells; ++i) {
        dsu_parent[i] = i;
    }

    auto find_set = [&](auto& self, int v) -> int {
        if (v == dsu_parent[v])
            return v;
        return dsu_parent[v] = self(self, dsu_parent[v]);
    };

    vector<long long> comp_sum(total_cells, 0);
    vector<int> tree_parent(total_cells, -1);
    vector<bool> valid_up(total_cells, false);
    vector<bool> activated(total_cells, false);

    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    for (const auto& cell : cells) {
        int u = cell.id;
        comp_sum[u] = cell.p;
        activated[u] = true;

        vector<int> neighbor_roots;
        for (int d = 0; d < 4; ++d) {
            int nr = cell.r + dr[d];
            int nc = cell.c + dc[d];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m) {
                int v = nr * m + nc;
                if (activated[v]) {
                    neighbor_roots.push_back(find_set(find_set, v));
                }
            }
        }

        sort(neighbor_roots.begin(), neighbor_roots.end());
        neighbor_roots.erase(unique(neighbor_roots.begin(), neighbor_roots.end()), neighbor_roots.end());

        for (int root : neighbor_roots) {
            tree_parent[root] = u;
            valid_up[root] = (comp_sum[root] >= cell.p);
            comp_sum[u] += comp_sum[root];
            dsu_parent[root] = u;
        }
    }

    vector<long long> memo(total_cells, -1);
    auto get_ans = [&](auto& self, int u) -> long long {
        if (memo[u] != -1) return memo[u];
        if (tree_parent[u] == -1 || !valid_up[u]) {
            return memo[u] = comp_sum[u];
        }
        return memo[u] = self(self, tree_parent[u]);
    };

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int id = i * m + j;
            cout << get_ans(get_ans, id) << (j == m - 1 ? "" : " ");
        }
        cout << "\n";
    }

    return 0;
}
